package banghak.home.halley.adapter.outbound.persistence;
import banghak.home.halley.domain.budget.*; import static banghak.home.halley.adapter.outbound.persistence.support.JooqMapping.toInstant; import org.jooq.DSLContext; import org.jooq.Record; import org.springframework.stereotype.Repository; import java.util.List; import java.util.Optional; import static banghak.home.halley.adapter.outbound.persistence.jdbc.HouseholdBudgetItemTable.*; import static banghak.home.halley.adapter.outbound.persistence.support.JooqMapping.toEnum;
@Repository public class HouseholdBudgetItemRepository { private final DSLContext dsl; public HouseholdBudgetItemRepository(DSLContext dsl){this.dsl=dsl;} public BudgetItem save(BudgetItem i){Long id=dsl.insertInto(TABLE).set(PLAN_ID,i.planId()).set(SEED_KEY,i.seedKey()).set(CATEGORY,i.category()).set(ITEM_NAME,i.itemName()).set(REQUIRED,i.required()).set(RECOMMENDED,i.recommended()).set(SELECTED,i.selected()).set(OWNED,i.owned()).set(BUDGET,i.budgetAmountWon()).set(CANDIDATE_NAME,i.candidateName()).set(CANDIDATE_URL,i.candidateUrl()).set(CANDIDATE_PRICE,i.candidatePriceWon()).set(ALTERNATIVE_NAME,i.alternativeName()).set(ALTERNATIVE_URL,i.alternativeUrl()).set(ALTERNATIVE_PRICE,i.alternativePriceWon()).set(CANDIDATE_STATUS,i.candidateFetchStatus().name()).set(ALTERNATIVE_STATUS,i.alternativeFetchStatus().name()).set(NOTE,i.note()).returningResult(ID).fetchOne().component1(); return findById(id).orElseThrow();} public Optional<BudgetItem> findById(Long id){return dsl.selectFrom(TABLE).where(ID.eq(id)).fetchOptional().map(this::map);} public List<BudgetItem> findByPlanId(Long id){return dsl.selectFrom(TABLE).where(PLAN_ID.eq(id)).orderBy(ID).fetch().map(this::map);} public void delete(Long id){dsl.deleteFrom(TABLE).where(ID.eq(id)).execute();} private BudgetItem map(Record r){return new BudgetItem(r.get(ID),r.get(PLAN_ID),r.get(SEED_KEY),r.get(CATEGORY),r.get(ITEM_NAME),r.get(REQUIRED),r.get(RECOMMENDED),r.get(SELECTED),r.get(OWNED),r.get(BUDGET),r.get(CANDIDATE_NAME),r.get(CANDIDATE_URL),r.get(CANDIDATE_PRICE),r.get(ALTERNATIVE_NAME),r.get(ALTERNATIVE_URL),r.get(ALTERNATIVE_PRICE),toEnum(ProductFetchStatus.class,r.get(CANDIDATE_STATUS)),toEnum(ProductFetchStatus.class,r.get(ALTERNATIVE_STATUS)),r.get(NOTE),toInstant(r.get(CREATED_AT)),toInstant(r.get(UPDATED_AT)));} }
